  auto before=manager.snapshot();auto disk=readText(manager.root/L"state.json");auto first=run();check(!first.saved&&first.error.empty()&&!first.cancelled,"Initial column preparation returns an owned read");check(manager.snapshot()==before&&readText(manager.root/L"state.json")==disk,"Initial preparation never writes settings or catalog data");
  {ColumnWriter writer(manager);std::atomic_bool waiting=false;task.start(manager,{}, {},[&](const char* point){if(std::string(point)=="waiting-read")waiting=true;});check(until([&]{return waiting.load();})&&!task.ready()&&writer.held,"A held catalog does not block the read caller");bool rejected=false;try{task.start(manager);}catch(...){rejected=true;}check(rejected,"A pending column owner rejects duplicate work");auto cancelled=task.finish();check(cancelled.cancelled&&!task.valid()&&writer.held,"Read cleanup cancels and joins before its model writer releases");writer.open();}
  manager.fileInfoDecisionPending=true;task.start(manager);Sleep(20);check(!task.ready(),"Read preparation waits for another accepted decision");check(task.finish().cancelled&&manager.fileInfoDecisionPending,"Read cancellation cannot release another decision guard");bool blocked=false;try{task.start(manager,draft);}catch(...){blocked=true;}check(blocked&&manager.fileInfoDecisionPending&&!task.valid(),"Save rejection preserves another command's guard");manager.fileInfoDecisionPending=false;
  auto failed=run({},[](const char* point){if(std::string(point)=="before-read")throw std::runtime_error("Owned read failure");});check(failed.error=="Owned read failure"&&!task.valid(),"A failed initial read is consumed for inline retry");check(run().error.empty(),"A cancelled or failed initial read can retry");
  {ColumnWriter writer(manager);std::atomic_bool waiting=false,notified=false;task.start(manager,draft,[&]{notified=true;throw std::runtime_error("Owned wake failure");},[&](const char* point){if(std::string(point)=="waiting-save")waiting=true;});check(until([&]{return waiting.load();})&&task.saving()&&manager.fileInfoDecisionPending&&!task.ready(),"Accepted Save owns its guard while the caller remains responsive");task.cancelRead();check(!task.ready()&&task.saving(),"Cancellation cannot abandon an accepted settings save");writer.open();check(until([&]{return notified.load();})&&task.ready()&&manager.fileInfoDecisionPending,"A throwing notification keeps acceptance until UI acknowledgement");auto saved=task.take();check(saved.saved&&saved.error.empty()&&saved.layout==draft.layout&&saved.widths==Json(draft.widths)&&!manager.fileInfoDecisionPending,"Save acknowledges its exact immutable result and releases its guard");}
  check(str(manager.state["Settings"],"UserAgent")=="Concurrent columns choice","Column merge preserves concurrent unrelated settings");auto saved=Json::parse(readText(manager.root/L"state.json"));check(saved["Settings"]["ListLayout"]==draft.layout&&saved["Settings"]["ColumnWidths"]==Json(draft.widths),"Accepted columns are durably persisted together");
  auto invalid=draft;invalid.layout["Order"][1]=0;bool rejected=false;before=manager.snapshot();disk=readText(manager.root/L"state.json");try{task.start(manager,invalid);}catch(...){rejected=true;}check(rejected&&!task.valid()&&!manager.fileInfoDecisionPending&&manager.snapshot()==before,"An invalid permutation is rejected before accepting or changing settings");invalid=draft;invalid.layout["Widths"][8]=346;rejected=false;try{task.start(manager,invalid);}catch(...){rejected=true;}check(rejected,"Visible widths must match the accepted remembered width");invalid=draft;invalid.widths[0]=1;rejected=false;try{task.start(manager,invalid);}catch(...){rejected=true;}check(rejected&&readText(manager.root/L"state.json")==disk,"Invalid widths add no catalog writes");
